#!/usr/bin/env python3
"""Writes core/iac-authoring/references/built-in-roles.yaml from Microsoft's role table.

A role assignment names a built-in role, and a misspelt one ("Storage Blob Contributor")
passes every check until the first apply. `check_pattern.py` and `check_spec.py` therefore
read role names from this file only, never from a model's memory. This script turns the
Markdown of *Azure built-in roles* (the table of name, description and id per category) into
the list.

The page's source is public:
    https://raw.githubusercontent.com/MicrosoftDocs/azure-docs/main/articles/role-based-access-control/built-in-roles.md

Usage:
    python3 update_built_in_roles.py <built-in-roles.md> [--out <built-in-roles.yaml>]
                                     [--retrieved YYYY-MM-DD]

Needs PyYAML. Exit 0 written, 2 could not run (no parser, no file, no role found).
"""

import argparse
import datetime
import os
import re
import sys

HERE = os.path.dirname(os.path.abspath(__file__))
DEFAULT_OUT = os.path.join(HERE, '..', '..', 'plugins', 'infrastructure-as-skills-azure',
                           'core', 'iac-authoring', 'references', 'built-in-roles.yaml')

# One table row: | <a name='x'></a>[Name](link) | description | guid |
ROW = re.compile(r"^>?\s*\|\s*(?:<a name='[^']*'></a>)?\[([^\]]+)\]\([^)]*\)\s*\|.*\|\s*"
                 r"([0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12})\s*\|\s*$")
PAGE_DATE = re.compile(r'^ms\.date:\s*(\S+)', re.M)

# Roles of a service's own role model, not of Azure RBAC: assigned through the service's
# API (Cosmos DB `sqlRoleAssignments`), so the page above does not list them.
DATA_PLANE = {
    'Cosmos DB Built-in Data Reader': '00000000-0000-0000-0000-000000000001',
    'Cosmos DB Built-in Data Contributor': '00000000-0000-0000-0000-000000000002',
}

# Roles Microsoft renamed: the definition id stayed, the display name changed. A spec written
# before the rename still names the old one; the checks say what it is called now.
RENAMED = {
    'Azure AI User': 'Foundry User',
}

HEADER = """\
# Generated by .github/scripts/update_built_in_roles.py from Microsoft's "Azure built-in
# roles" page. Do not edit by hand - run the script on a fresh copy of the page.
#
# The one list of role names the checks accept: check_pattern.py for a pattern's
# wiring.role_assignments, check_spec.py for a spec's. `roles` are Azure RBAC roles (name ->
# role definition id); `data_plane` are roles of a service's own role model, assigned through
# that service and not through Microsoft.Authorization; `renamed` maps a role's former name
# to its current one (same definition id).
"""


def main():
    ap = argparse.ArgumentParser(description='Write built-in-roles.yaml from the built-in roles page.')
    ap.add_argument('page', help='the Markdown source of the built-in roles page')
    ap.add_argument('--out', default=DEFAULT_OUT, help='the file to write')
    ap.add_argument('--retrieved', default=datetime.date.today().isoformat(), help='the date the page was fetched')
    args = ap.parse_args()

    try:
        import yaml
    except ImportError:
        print('[fail] no YAML parser available - pip install pyyaml', file=sys.stderr)
        return 2
    if not os.path.isfile(args.page):
        print(f"[fail] no such file: {args.page}", file=sys.stderr)
        return 2

    with open(args.page, encoding='utf-8') as f:
        text = f.read()
    roles = {}
    for line in text.splitlines():
        m = ROW.match(line)
        if m:
            roles[m.group(1).strip()] = m.group(2)
    if len(roles) < 100:
        print(f"[fail] {len(roles)} role(s) found in {args.page} - the page's table format changed", file=sys.stderr)
        return 2

    page_date = PAGE_DATE.search(text)
    doc = {
        'retrieved': args.retrieved,
        'page_dated': page_date.group(1) if page_date else None,
        'roles': dict(sorted(roles.items(), key=lambda kv: kv[0].lower())),
        'data_plane': DATA_PLANE,
        'renamed': {old: new for old, new in RENAMED.items() if new in roles},
    }
    with open(args.out, 'w', encoding='utf-8', newline='\n') as f:
        f.write(HEADER)
        yaml.safe_dump(doc, f, sort_keys=False, allow_unicode=True, width=200)
    print(f"[ ok ] {len(roles)} role(s) + {len(DATA_PLANE)} data-plane role(s) -> {os.path.relpath(args.out)}")
    return 0


if __name__ == '__main__':
    sys.exit(main())
